#!/usr/bin/env python3
"""Buffered I/O and INI stop after the first failure, including empty calls."""
import os
from pathlib import Path
import subprocess
import tempfile
ROOT=Path(__file__).resolve().parents[1]
DYN=str(Path(os.environ.get('DYN',ROOT/'build/dyn-release')).resolve())
SOURCE='use "std/io"\nuse "std/bufio"\nuse "std/errors"\nuse "std/encoding/ini"\nstruct Sink { calls: usize }\nfn fail(data: rawptr, source: []const u8) io.Result {\n  state := #cast(*Sink, data)\n  state.calls += 1\n  return io.Result{ transferred: 1, error: -13, kind: errors.Kind.PermissionDenied, status: io.Status.Error }\n}\nfn fail_read(data: rawptr, destination: []u8) io.Result {\n  state := #cast(*Sink, data)\n  state.calls += 1\n  destination[0] = \'x\'\n  return io.Result{ transferred: 1, error: -13, kind: errors.Kind.PermissionDenied, status: io.Status.Error }\n}\nfn two_read(data: rawptr, destination: []u8) io.Result {\n  state := #cast(*Sink, data)\n  state.calls += 1\n  destination[0] = \'a\'\n  destination[1] = \'b\'\n  return io.Result{ transferred: 2, error: -13, kind: errors.Kind.PermissionDenied, status: io.Status.Error }\n}\nfn main() {\n  sink: Sink\n  storage: [8]u8 = []\n  writer := bufio.writer(io.Writer{ data: &sink, write: fail }, storage[..0])\n  first := io.write(bufio.writer_adapter(&writer), "abc")\n  second := io.write(bufio.writer_adapter(&writer), "abc")\n  flushed := bufio.writer_flush(&writer)\n  _ = io.println(io.stdout(), "writer calls={} first={} second={} flush={}", sink.calls, first.transferred, second.transferred, flushed.error)\n  writer.used = 9\n  kept := bufio.writer_flush(&writer)\n  if kept.error != -13 || writer.used != 9 { #panic("first error replaced") }\n  adapter := bufio.writer_adapter(&writer)\n  empty_write := adapter.write(adapter.data, "")\n  if empty_write.error != -13 || sink.calls != 1 { #panic("empty writer") }\n  for capacity in [0, 8] {\n    reads: Sink\n    reader := bufio.reader(io.Reader{ data: &reads, read: fail_read }, storage[..#cast(usize, capacity)])\n    output: [4]u8 = []\n    first_read := io.read(bufio.reader_adapter(&reader), output[..])\n    read_adapter := bufio.reader_adapter(&reader)\n    later_read := read_adapter.read(read_adapter.data, output[..0])\n    line := bufio.read_line(&reader, output[..0])\n    until := bufio.read_until(&reader, output[..], 10)\n    if first_read.transferred != 1 || first_read.error != -13 || later_read.error != -13 || line.error != -13 || until.error != -13 || reads.calls != 1 { #panic("reader sticky failure") }\n  }\n  reads: Sink\n  buffered := bufio.reader(io.Reader{ data: &reads, read: two_read }, storage[..])\n  output: [1]u8 = []\n  partial := io.read(bufio.reader_adapter(&buffered), output[..])\n  position := buffered.start\n  stopped := io.read(bufio.reader_adapter(&buffered), output[..])\n  if partial.transferred != 1 || output[0] != \'a\' || stopped.transferred != 0 || stopped.error != -13 || buffered.start != position || reads.calls != 1 { #panic("buffered reader consumed after error") }\n  for capacity in [2, 8] {\n    writes: Sink\n    staged := bufio.writer(io.Writer{ data: &writes, write: fail }, storage[..#cast(usize, capacity)])\n    first_write := io.write(bufio.writer_adapter(&staged), "abcdef")\n    flushed_stage := bufio.writer_flush(&staged)\n    if capacity == 8 && (first_write.transferred != 6 || flushed_stage.transferred != 1 || staged.used != 5) { #panic("flush partial count") }\n    if capacity == 2 && (first_write.transferred != 1 || first_write.error != -13) { #panic("direct partial count") }\n    pending := staged.used\n    again := io.write(bufio.writer_adapter(&staged), "x")\n    if again.error != -13 || again.transferred != 0 || staged.used != pending || writes.calls != 1 { #panic("buffered writer sticky failure") }\n  }\n  scan := ini.scanner("bad\\nx=1")\n  item := ini.next(&scan)\n  offset := scan.offset\n  later := ini.next(&scan)\n  _ = io.println(io.stdout(), "ini first={} later={} line={} errors={} stable={}", item.ok, later.ok, scan.error_line, scan.errors, offset == scan.offset)\n  if sink.calls != 1 || first.transferred != 1 || first.error != -13 || second.transferred != 0 || second.error != -13 || flushed.error != -13 { #panic("writer sticky failure") }\n  if item.ok || later.ok || scan.error != ini.ErrorKind.Syntax || scan.error_line != 1 || scan.errors != 1 || scan.offset != offset { #panic("ini sticky failure") }\n}\n'
with tempfile.TemporaryDirectory(prefix='dyn-std-sticky-') as directory:
    work=Path(directory)
    (work/'main.dyn').write_text(SOURCE)
    for mode in ('debug','release'):
        subprocess.run([DYN,'build',str(work),'--'+mode,'--quiet','--no-cache','--output',str(work/'test')],check=True,timeout=120)
        result=subprocess.run([str(work/'test')],capture_output=True,timeout=10)
        assert result.returncode==0,(result.stdout,result.stderr)
        print('PASS buffered I/O and INI sticky errors '+mode,flush=True)
